import networkx as nx
G = nx.Graph()
for i in range(16):
    for j in range(i+1, 16):
        G.add_edge(i, j)
max_independent_set = 5
vertex_connectivity = 5
if len(max(nx.independent_sets(G), key=len)) = max_independent_set and nx.vertex_connectivity(G) >= vertex_connectivity:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
